import sys

def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    T = int(data[index])
    index += 1

    results = []

    for _ in range(T):
        N = int(data[index])
        k = int(data[index + 1])
        index += 2

        A = list(map(int, data[index:index + N]))
        index += N

        results.append(solve(N, k, A))

    return results

def solve(N, k, A):
    count = 0
    for i in range(N):
        for j in range(i + 1, N):
            if (A[i] | A[j]) + (A[i] ^ A[j]) + (A[i] & A[j]) == k + A[j]:
                count += 1
    return count

def main():
    results = read_input()
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
